import 'package:flutter/widgets.dart';

/// UI strings in the 16 app languages. `L10n.of(context).s('key')`, with
/// {placeholders} filled by `f('key', {'n': 3})`. Missing keys fall back to English.
class L10n {
  L10n(this.code);
  final String code;

  static const languages = {
    'it': 'Italiano', 'en': 'English', 'fr': 'Français', 'de': 'Deutsch', 'es': 'Español', 'pt': 'Português',
    'nl': 'Nederlands', 'pl': 'Polski', 'ro': 'Română', 'sv': 'Svenska', 'ru': 'Русский', 'uk': 'Українська',
    'tr': 'Türkçe', 'ar': 'العربية', 'zh': '中文', 'ja': '日本語',
  };

  static L10n forCode(String? code) => L10n(languages.containsKey(code) ? code! : 'en');

  static L10n of(BuildContext context) => forCode(Localizations.localeOf(context).languageCode);

  bool get rtl => code == 'ar';

  /// Whether this language translates [key] itself (no English fallback).
  bool translates(String key) => _strings[code]?.containsKey(key) ?? false;

  String s(String key) => _strings[code]?[key] ?? _strings['en']![key] ?? key;

  String f(String key, Map<String, Object> vars) {
    var text = s(key);
    vars.forEach((k, v) => text = text.replaceAll('{$k}', '$v'));
    return text;
  }

  String category(String c) => s('cat_$c');
}

